Here's the complete implementation of the `ConsultationController` with all the necessary endpoints based on your requirements:

```csharp
[Route("api/[controller]")]
[ApiController]
[HealthSysHubAutherize]
public class ConsultationController : ControllerBase
{
    private readonly IConsultationManager _consultationManager;
    
    public ConsultationController(IConsultationManager consultationManager)
    {
        _consultationManager = consultationManager;
    }

    [HttpGet]
    [Route("GetAllConsultationsAsync")]
    public async Task<IActionResult> GetAllConsultationsAsync()
    {
        try
        {
            var response = await _consultationManager.GetConsultationDetailsAsync();
            return Ok(response);
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, ex.Message);
        }
    }

    [HttpGet]
    [Route("GetConsultationByAppointmentIdAsync/{appointmentId}")]
    public async Task<IActionResult> GetConsultationByAppointmentIdAsync(Guid appointmentId)
    {
        try
        {
            var response = await _consultationManager.GetConsultationDetailsByAppointmentIdAsync(appointmentId);
            return Ok(response);
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, ex.Message);
        }
    }

    [HttpGet]
    [Route("GetConsultationByConsultationIdAsync/{consultationId}")]
    public async Task<IActionResult> GetConsultationByConsultationIdAsync(Guid consultationId)
    {
        try
        {
            var response = await _consultationManager.GetConsultationDetailsByConsultationIdAsync(consultationId);
            return Ok(response);
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, ex.Message);
        }
    }

    [HttpGet]
    [Route("GetConsultationsByDoctorAsync/{doctorId}")]
    public async Task<IActionResult> GetConsultationsByDoctorAsync(Guid doctorId)
    {
        try
        {
            var response = await _consultationManager.GetConsultationDetailsByDoctorAsync(doctorId);
            return Ok(response);
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, ex.Message);
        }
    }

    [HttpGet]
    [Route("GetConsultationsByHospitalAsync/{hospitalId}")]
    public async Task<IActionResult> GetConsultationsByHospitalAsync(Guid hospitalId)
    {
        try
        {
            var response = await _consultationManager.GetConsultationDetailsByHospitalAsync(hospitalId);
            return Ok(response);
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, ex.Message);
        }
    }

    // Add more endpoints as needed for other consultation-related operations
    // For example:
    /*
    [HttpPost]
    [Route("CreateConsultationAsync")]
    public async Task<IActionResult> CreateConsultationAsync([FromBody] ConsultationCreateModel model)
    {
        try
        {
            var response = await _consultationManager.CreateConsultationAsync(model);
            return Ok(response);
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, ex.Message);
        }
    }
    */
}
```

Key features of this implementation:

1. Follows the same pattern as your example with proper error handling
2. Includes all the required endpoints for the consultation operations
3. Uses proper RESTful route naming conventions
4. Maintains consistent parameter naming (using Guid IDs in routes)
5. Includes the `[HealthSysHubAutherize]` attribute on all endpoints
6. Each endpoint follows the same try-catch pattern for consistent error handling

Note that I've included a commented example of how you might add additional endpoints (like a POST endpoint for creating consultations) if needed in the future. You can uncomment and modify these as your API requirements grow.

The controller assumes your `IConsultationManager` interface has all the corresponding methods that are being called. Make sure those are properly defined in your interface.

